import * as THREE from 'three/webgpu';
import { texture, uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const width = 512;
  const height = 320;
  const aspect = width / height;

  const planeHeight = 1.2;
  const planeWidth = planeHeight * aspect;

  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  const map = ctx.textureLoader.load('/prism-mock/home/nodes/floating-accent.png');
  map.colorSpace = THREE.SRGBColorSpace;

  // atlas region 0,0,512,320 with total atlas assumed same size as region (full image use)
  const atlasWidth = 512;
  const atlasHeight = 320;
  const rect = { x: 0, y: 0, w: 512, h: 320 };

  const uOffset = rect.x / atlasWidth;
  const vOffset = 1.0 - (rect.y + rect.h) / atlasHeight;
  const uScale = rect.w / atlasWidth;
  const vScale = rect.h / atlasHeight;

  const materialUv = uv().mul(vec2(uScale, vScale)).add(vec2(uOffset, vOffset));

  const material = new THREE.MeshBasicNodeMaterial();
  material.map = map;
  material.mapNode = texture(map, materialUv);
  material.transparent = true;
  material.depthWrite = false;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'hub-features-card-1-accent';

  const node = new THREE.Object3D();
  node.name = 'hub-features-card-1-accent-sprite';
  node.add(mesh);

  node.position.set(0, -0.3, 0);
  node.rotation.set(0, 0, 0);
  node.scale.set(1, 1, 1);

  // Billboard behavior handled in update loop if ctx supports it
  const billboardUpdate = () => {
    if (ctx.camera) {
      mesh.quaternion.copy(ctx.camera.quaternion);
    }
  };

  if (ctx.onUpdate) {
    ctx.onUpdate(billboardUpdate);
  }

  node.userData.handlers = {};

  node.userData.cleanup = () => {
    if (ctx.offUpdate) {
      ctx.offUpdate(billboardUpdate);
    }
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
  };

  return node;
}
